//! Rust FFI bindings for Linux kernel-internal APIs.
//!
//! Generated by bindgen at build time from the configured kernel headers.

#![no_std]
#![allow(
    non_snake_case,
    non_upper_case_globals,
    non_camel_case_types,
    improper_ctypes,
    dead_code,
    clippy::all
)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
